//! `forge_provider::verify`: checksums, size, minisign and PGP with keys generated by the
//! tests, Authenticode on real Windows files, job progress and cancellation. The
//! `*_online` tests (ignored by default) check real upstream signatures with the embedded
//! keyrings; they download into `FORGEBOX_TEST_CACHE` (default: `%TEMP%/forgebox-test-cache`)
//! and reuse files already there.

mod support;

use std::io::Cursor;
use std::path::{Path, PathBuf};
use std::time::Duration;

use forge_core::event::EventBus;
use forge_core::jobs::{JobRegistry, JobState};
use forge_provider::verify::{
    Expect, PgpKeyring, Signature, SignatureReport, Verifier, VerifyReport, verify_file,
};
use pgp::composed::{
    ArmorOptions, DetachedSignature, KeyType, SecretKeyParamsBuilder, SignedSecretKey,
    SubkeyParamsBuilder,
};
use pgp::crypto::hash::HashAlgorithm;
use pgp::ser::Serialize as _;
use pgp::types::Password;
use sha2::{Digest, Sha512};
use support::sha256_hex;

fn sha512_hex(data: &[u8]) -> String {
    Sha512::digest(data)
        .iter()
        .map(|b| format!("{b:02x}"))
        .collect()
}

fn write(dir: &Path, name: &str, data: &[u8]) -> PathBuf {
    let path = dir.join(name);
    std::fs::write(&path, data).unwrap();
    path
}

async fn verify(path: &Path, expect: Expect) -> forge_core::Result<VerifyReport> {
    verify_file(path, expect).await
}

#[tokio::test]
async fn sha256_ok_and_mismatch() {
    let dir = tempfile::tempdir().unwrap();
    let data = support::payload(3 * 1024 * 1024 + 17);
    let path = write(dir.path(), "tool.zip", &data);

    let report = verify(
        &path,
        Expect::sha256(sha256_hex(&data)).size(data.len() as u64),
    )
    .await
    .unwrap();
    assert_eq!(report.sha256.as_deref(), Some(sha256_hex(&data).as_str()));
    assert_eq!(report.size, data.len() as u64);
    assert!(!report.unverified);
    assert_eq!(report.sha512, None);

    // Upper-case expectations are accepted.
    verify(&path, Expect::sha256(sha256_hex(&data).to_uppercase()))
        .await
        .unwrap();

    let err = verify(&path, Expect::sha256(sha256_hex(b"other")))
        .await
        .unwrap_err();
    assert_eq!(err.code(), "verification_failed");
    assert!(err.to_string().contains("sha256"), "{err}");
}

#[tokio::test]
async fn sha512_ok_and_mismatch() {
    let dir = tempfile::tempdir().unwrap();
    let data = b"forgebox sha512".repeat(1000);
    let path = write(dir.path(), "a.tar.xz", &data);
    let report = verify(&path, Expect::sha512(sha512_hex(&data)))
        .await
        .unwrap();
    assert_eq!(report.sha512.as_deref(), Some(sha512_hex(&data).as_str()));
    assert_eq!(report.sha256, None);
    let err = verify(&path, Expect::sha512(sha512_hex(b"x")))
        .await
        .unwrap_err();
    assert_eq!(err.code(), "verification_failed");
}

#[tokio::test]
async fn size_and_expectation_errors() {
    let dir = tempfile::tempdir().unwrap();
    let path = write(dir.path(), "f.bin", b"12345");
    let sha = sha256_hex(b"12345");

    let err = verify(&path, Expect::sha256(&sha).size(4))
        .await
        .unwrap_err();
    assert_eq!(err.code(), "verification_failed");
    assert!(err.to_string().contains("size"), "{err}");

    let err = verify(&path, Expect::sha256("abc")).await.unwrap_err();
    assert_eq!(err.code(), "invalid_input");

    let err = verify(&dir.path().join("missing"), Expect::sha256(&sha))
        .await
        .unwrap_err();
    assert_eq!(err.code(), "not_found");

    let err = verify(dir.path(), Expect::sha256(&sha)).await.unwrap_err();
    assert_eq!(err.code(), "invalid_input");
}

#[tokio::test]
async fn checksum_is_mandatory_unless_allowed() {
    let dir = tempfile::tempdir().unwrap();
    let path = write(dir.path(), "f.bin", b"no hash");
    let err = verify(&path, Expect::default()).await.unwrap_err();
    assert_eq!(err.code(), "verification_failed");
    assert!(err.to_string().contains("--allow-unverified"), "{err}");

    let report = verify(&path, Expect::unverified()).await.unwrap();
    assert!(report.unverified);
    assert_eq!(
        report.sha256.as_deref(),
        Some(sha256_hex(b"no hash").as_str())
    );
}

// ---------- minisign ----------

struct MinisignKey {
    pair: minisign::KeyPair,
}

impl MinisignKey {
    fn new() -> Self {
        Self {
            pair: minisign::KeyPair::generate_unencrypted_keypair().unwrap(),
        }
    }

    fn sign(&self, data: &[u8]) -> String {
        minisign::sign(
            Some(&self.pair.pk),
            &self.pair.sk,
            Cursor::new(data),
            Some("timestamp:1 file:tool.zip"),
            Some("signature from forgebox test key"),
        )
        .unwrap()
        .into_string()
    }

    fn base64(&self) -> String {
        self.pair.pk.to_base64()
    }

    fn pub_file(&self) -> String {
        self.pair.pk.to_box().unwrap().into_string()
    }
}

#[tokio::test]
async fn minisign_ok_and_forged() {
    let dir = tempfile::tempdir().unwrap();
    let data = support::payload(2 * 1024 * 1024 + 3);
    let path = write(dir.path(), "tool.zip", &data);
    let key = MinisignKey::new();
    let sig = key.sign(&data);

    for pubkey in [key.base64(), key.pub_file()] {
        let report = verify(
            &path,
            Expect::sha256(sha256_hex(&data)).signature(Signature::Minisign {
                sig: sig.clone(),
                pubkey,
            }),
        )
        .await
        .unwrap();
        match report.signature {
            Some(SignatureReport::Minisign { trusted_comment }) => {
                assert_eq!(trusted_comment, "timestamp:1 file:tool.zip");
            }
            other => panic!("unexpected {other:?}"),
        }
    }

    // Signature of other content.
    let other = key.sign(b"something else");
    let err = verify(
        &path,
        Expect::sha256(sha256_hex(&data)).signature(Signature::Minisign {
            sig: other,
            pubkey: key.base64(),
        }),
    )
    .await
    .unwrap_err();
    assert_eq!(err.code(), "verification_failed");

    // Signed by another key.
    let stranger = MinisignKey::new();
    let err = verify(
        &path,
        Expect::sha256(sha256_hex(&data)).signature(Signature::Minisign {
            sig: stranger.sign(&data),
            pubkey: key.base64(),
        }),
    )
    .await
    .unwrap_err();
    assert_eq!(err.code(), "verification_failed");

    // Garbage signature file.
    let err = verify(
        &path,
        Expect::sha256(sha256_hex(&data)).signature(Signature::Minisign {
            sig: "not a signature".into(),
            pubkey: key.base64(),
        }),
    )
    .await
    .unwrap_err();
    assert_eq!(err.code(), "verification_failed");

    // Bad public key is a configuration problem.
    let err = verify(
        &path,
        Expect::sha256(sha256_hex(&data)).signature(Signature::Minisign {
            sig,
            pubkey: "RWnope".into(),
        }),
    )
    .await
    .unwrap_err();
    assert_eq!(err.code(), "invalid_input");
}

// ---------- PGP ----------

fn pgp_key(uid: &str, signing_subkey: bool) -> SignedSecretKey {
    let mut params = SecretKeyParamsBuilder::default();
    params
        .key_type(KeyType::Ed25519Legacy)
        .can_certify(true)
        .can_sign(true)
        .primary_user_id(uid.into());
    if signing_subkey {
        params.subkey(
            SubkeyParamsBuilder::default()
                .key_type(KeyType::Ed25519Legacy)
                .can_sign(true)
                .build()
                .unwrap(),
        );
    }
    params
        .build()
        .unwrap()
        .generate(rand::thread_rng())
        .unwrap()
}

fn armored_public(key: &SignedSecretKey) -> String {
    key.to_public_key()
        .to_armored_string(ArmorOptions::default())
        .unwrap()
}

fn keyring(name: &str, keys: &[&SignedSecretKey]) -> PgpKeyring {
    let armored = keys
        .iter()
        .map(|k| format!("# test key\n{}", armored_public(k)))
        .collect::<Vec<_>>()
        .join("\n");
    PgpKeyring::Armored {
        name: name.into(),
        armored,
    }
}

fn detached(sig: DetachedSignature, armored: bool) -> Vec<u8> {
    if armored {
        sig.to_armored_bytes(ArmorOptions::default()).unwrap()
    } else {
        sig.to_bytes().unwrap()
    }
}

fn sign_primary(key: &SignedSecretKey, data: &[u8], armored: bool) -> Vec<u8> {
    let sig = DetachedSignature::sign_binary_data(
        rand::thread_rng(),
        &key.primary_key,
        &Password::empty(),
        HashAlgorithm::Sha256,
        data,
    )
    .unwrap();
    detached(sig, armored)
}

fn sign_subkey(key: &SignedSecretKey, data: &[u8]) -> Vec<u8> {
    let sig = DetachedSignature::sign_binary_data(
        rand::thread_rng(),
        &key.secret_subkeys[0].key,
        &Password::empty(),
        HashAlgorithm::Sha512,
        data,
    )
    .unwrap();
    detached(sig, true)
}

fn pgp_expect(data: &[u8], sig_path: &Path, keyring: PgpKeyring) -> Expect {
    Expect::sha256(sha256_hex(data)).signature(Signature::Pgp {
        sig_path: sig_path.to_path_buf(),
        keyring,
    })
}

#[tokio::test]
async fn pgp_detached_ok_armored_and_binary() {
    let dir = tempfile::tempdir().unwrap();
    let data = support::payload(1024 * 1024 + 5);
    let path = write(dir.path(), "nginx-1.0.zip", &data);
    let signer = pgp_key("Release Signer <release@example.test>", false);
    let other = pgp_key("Someone Else <else@example.test>", false);
    let ring = keyring("test", &[&other, &signer]);

    for armored in [true, false] {
        let sig_path = write(
            dir.path(),
            if armored { "a.asc" } else { "a.sig" },
            &sign_primary(&signer, &data, armored),
        );
        let report = verify(&path, pgp_expect(&data, &sig_path, ring.clone()))
            .await
            .unwrap();
        let fingerprint = ring.fingerprints().unwrap()[1].clone();
        match report.signature {
            Some(SignatureReport::Pgp {
                keyring,
                signer,
                primary,
            }) => {
                assert_eq!(keyring, "test");
                assert_eq!(signer, fingerprint);
                assert_eq!(primary, fingerprint);
            }
            other => panic!("unexpected {other:?}"),
        }
    }
}

#[tokio::test]
async fn pgp_signing_subkey_is_accepted() {
    let dir = tempfile::tempdir().unwrap();
    let data = b"SHASUMS256.txt content\n".to_vec();
    let path = write(dir.path(), "SHASUMS256.txt", &data);
    let key = pgp_key("Releaser <r@example.test>", true);
    let sig_path = write(dir.path(), "SHASUMS256.txt.asc", &sign_subkey(&key, &data));
    let ring = keyring("subkeys", &[&key]);
    let report = verify(&path, pgp_expect(&data, &sig_path, ring.clone()))
        .await
        .unwrap();
    match report.signature {
        Some(SignatureReport::Pgp {
            signer, primary, ..
        }) => {
            assert_eq!(primary, ring.fingerprints().unwrap()[0]);
            assert_ne!(signer, primary, "made by the subkey");
        }
        other => panic!("unexpected {other:?}"),
    }
}

#[tokio::test]
async fn pgp_forged_signatures_are_rejected() {
    let dir = tempfile::tempdir().unwrap();
    let data = support::payload(256 * 1024);
    let path = write(dir.path(), "tool.zip", &data);
    let trusted = pgp_key("Trusted <t@example.test>", false);
    let attacker = pgp_key("Attacker <a@example.test>", false);
    let ring = keyring("trusted", &[&trusted]);

    // Valid signature by a key that is not in the keyring.
    let sig_path = write(dir.path(), "1.asc", &sign_primary(&attacker, &data, true));
    let err = verify(&path, pgp_expect(&data, &sig_path, ring.clone()))
        .await
        .unwrap_err();
    assert_eq!(err.code(), "verification_failed");
    assert!(
        err.to_string().contains("not in the trusted keyring"),
        "{err}"
    );

    // Trusted key, but over other content (file swapped, hash updated by the attacker).
    let sig_path = write(dir.path(), "2.asc", &sign_primary(&trusted, b"other", true));
    let err = verify(&path, pgp_expect(&data, &sig_path, ring.clone()))
        .await
        .unwrap_err();
    assert_eq!(err.code(), "verification_failed");
    assert!(err.to_string().contains("invalid signature"), "{err}");

    // Garbage instead of a signature.
    let sig_path = write(
        dir.path(),
        "3.asc",
        b"-----BEGIN PGP SIGNATURE-----\n\nxx\n",
    );
    let err = verify(&path, pgp_expect(&data, &sig_path, ring.clone()))
        .await
        .unwrap_err();
    assert_eq!(err.code(), "verification_failed");

    // Missing signature file.
    let err = verify(
        &path,
        pgp_expect(&data, &dir.path().join("missing.asc"), ring),
    )
    .await
    .unwrap_err();
    assert_eq!(err.code(), "not_found");

    // Unknown embedded keyring.
    let sig_path = write(dir.path(), "4.asc", &sign_primary(&trusted, &data, true));
    let err = verify(
        &path,
        pgp_expect(&data, &sig_path, PgpKeyring::embedded("nope")),
    )
    .await
    .unwrap_err();
    assert_eq!(err.code(), "not_found");

    // The embedded nginx keyring does not trust the test key.
    let err = verify(
        &path,
        pgp_expect(&data, &sig_path, PgpKeyring::embedded("nginx")),
    )
    .await
    .unwrap_err();
    assert_eq!(err.code(), "verification_failed");
}

// ---------- Authenticode ----------

#[cfg(windows)]
fn notepad() -> PathBuf {
    let windir = std::env::var_os("SystemRoot").unwrap_or_else(|| r"C:\Windows".into());
    Path::new(&windir).join("System32").join("notepad.exe")
}

#[cfg(windows)]
fn sha256_of(path: &Path) -> String {
    sha256_hex(&std::fs::read(path).unwrap())
}

#[cfg(windows)]
#[tokio::test]
async fn authenticode_trusted_microsoft_binary() {
    let exe = notepad();
    let report = verify(
        &exe,
        Expect::sha256(sha256_of(&exe)).signature(Signature::Authenticode {
            expected_publisher: None,
        }),
    )
    .await
    .unwrap();
    let Some(SignatureReport::Authenticode(info)) = &report.signature else {
        panic!("unexpected {report:?}");
    };
    assert!(info.signed && info.trusted, "{info:?}");
    let publisher = info.publisher.clone().unwrap();
    assert!(publisher.contains("Microsoft"), "{publisher}");

    // Pinned to the exact publisher name.
    verify(
        &exe,
        Expect::sha256(sha256_of(&exe)).signature(Signature::Authenticode {
            expected_publisher: Some(publisher.clone()),
        }),
    )
    .await
    .unwrap();
    let err = verify(
        &exe,
        Expect::sha256(sha256_of(&exe)).signature(Signature::Authenticode {
            expected_publisher: Some("Cloudflare, Inc.".into()),
        }),
    )
    .await
    .unwrap_err();
    assert_eq!(err.code(), "verification_failed");
    assert!(err.to_string().contains(&publisher), "{err}");
}

#[cfg(windows)]
#[tokio::test]
async fn authenticode_unsigned_binary_is_rejected() {
    let exe = std::env::current_exe().unwrap();
    let err = verify(
        &exe,
        Expect::sha256(sha256_of(&exe)).signature(Signature::Authenticode {
            expected_publisher: None,
        }),
    )
    .await
    .unwrap_err();
    assert_eq!(err.code(), "verification_failed");
    assert!(
        err.to_string().contains("no Authenticode signature"),
        "{err}"
    );
}

// ---------- jobs ----------

#[tokio::test]
async fn progress_and_result_inside_a_job() {
    let dir = tempfile::tempdir().unwrap();
    let data = support::payload(8 * 1024 * 1024);
    let path = write(dir.path(), "big.zip", &data);
    let bus = EventBus::new();
    let jobs = JobRegistry::new(bus.clone());
    let verifier = Verifier::new(&forge_core::platform::current());
    let expect = Expect::sha256(sha256_hex(&data));
    let handle = jobs.spawn(forge_core::jobs::JobSpec::new("verify"), {
        let path = path.clone();
        move |ctx| async move { verifier.verify_in_job(&ctx, path, expect).await }
    });
    let info = handle.wait(Duration::from_secs(60)).await.unwrap();
    assert_eq!(info.state, JobState::Done, "{info:?}");
    assert_eq!(info.progress.bytes_done, Some(data.len() as u64));
    assert_eq!(info.progress.bytes_total, Some(data.len() as u64));
    assert_eq!(info.progress.message.as_deref(), Some("Verificando sha256"));
    let report: VerifyReport = serde_json::from_value(info.result.unwrap()).unwrap();
    assert_eq!(report.sha256.unwrap(), sha256_hex(&data));
}

#[tokio::test]
async fn cancelled_job_stops_hashing() {
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("huge.bin");
    {
        // Sparse-ish large file: content does not matter, size does.
        let file = std::fs::File::create(&path).unwrap();
        file.set_len(512 * 1024 * 1024).unwrap();
    }
    let bus = EventBus::new();
    let jobs = JobRegistry::new(bus.clone());
    let verifier = Verifier::new(&forge_core::platform::current());
    let expect = Expect::sha256("00".repeat(32));
    let handle = jobs.spawn(forge_core::jobs::JobSpec::new("verify"), {
        let path = path.clone();
        move |ctx| async move { verifier.verify_in_job(&ctx, path, expect).await }
    });
    tokio::time::sleep(Duration::from_millis(20)).await;
    assert!(handle.cancel());
    let info = handle.wait(Duration::from_secs(30)).await.unwrap();
    assert_eq!(info.state, JobState::Cancelled, "{info:?}");
}

// ---------- online: real upstream signatures with the embedded keyrings ----------

fn cache_dir() -> PathBuf {
    let dir = std::env::var_os("FORGEBOX_TEST_CACHE")
        .map(PathBuf::from)
        .unwrap_or_else(|| std::env::temp_dir().join("forgebox-test-cache"));
    std::fs::create_dir_all(&dir).unwrap();
    dir
}

/// Downloads `url` to `cache/<name>` through the download engine (system proxy), unless a
/// file with the expected sha256 is already there.
async fn cached(url: &str, name: &str, sha256: &str) -> PathBuf {
    let dest = cache_dir().join(name);
    if dest.is_file() && sha256_hex(&std::fs::read(&dest).unwrap()) == sha256 {
        return dest;
    }
    let harness = support::Harness::new(|c| {
        c.proxy = forge_provider::download::ProxySetting::System;
    });
    let mut events = harness.events();
    let job = harness
        .manager
        .download(
            forge_provider::download::DownloadRequest::new(vec![url.parse().unwrap()], &dest)
                .expected_sha256(sha256),
        )
        .await
        .unwrap();
    harness.wait_terminal(&mut events, job).await;
    let info = harness.jobs.get(job).unwrap();
    assert_eq!(info.state, JobState::Done, "{url}: {info:?}");
    dest
}

#[tokio::test]
#[ignore = "downloads from nginx.org"]
async fn nginx_release_pgp_online() {
    // nginx-1.28.3.zip as published on 2026-10-26; its sha256 is pinned here because nginx
    // publishes only PGP signatures.
    let zip = cached(
        "https://nginx.org/download/nginx-1.28.3.zip",
        "nginx-1.28.3.zip",
        "aad7bf75d669ece7671688bfdf35f1093d6a30d2e62469405f4d55d8d82d5fd3",
    )
    .await;
    let asc = cache_dir().join("nginx-1.28.3.zip.asc");
    if !asc.is_file() {
        let sha = {
            // The signature itself is not pinned: download it unverified, the PGP check
            // is what validates it.
            let harness = support::Harness::new(|c| {
                c.proxy = forge_provider::download::ProxySetting::System;
            });
            let mut events = harness.events();
            let job = harness
                .manager
                .download(forge_provider::download::DownloadRequest::new(
                    vec![
                        "https://nginx.org/download/nginx-1.28.3.zip.asc"
                            .parse()
                            .unwrap(),
                    ],
                    &asc,
                ))
                .await
                .unwrap();
            harness.wait_terminal(&mut events, job).await;
            harness.jobs.get(job).unwrap().state
        };
        assert_eq!(sha, JobState::Done);
    }
    let report = verify(
        &zip,
        Expect::sha256("aad7bf75d669ece7671688bfdf35f1093d6a30d2e62469405f4d55d8d82d5fd3")
            .signature(Signature::Pgp {
                sig_path: asc,
                keyring: PgpKeyring::embedded("nginx"),
            }),
    )
    .await
    .unwrap();
    println!("{report:?}");
    match report.signature {
        Some(SignatureReport::Pgp { primary, .. }) => {
            // Roman Arutyunyan signed 1.28.3.
            assert_eq!(primary, "43387825DDB1BB97EC36BA5D007C8D7C15D87369");
        }
        other => panic!("unexpected {other:?}"),
    }

    // The same signature does not cover a modified archive.
    let dir = tempfile::tempdir().unwrap();
    let mut bytes = std::fs::read(&zip).unwrap();
    bytes[100] ^= 1;
    let tampered = write(dir.path(), "nginx-1.28.3.zip", &bytes);
    let err = verify(
        &tampered,
        Expect::unverified().signature(Signature::Pgp {
            sig_path: cache_dir().join("nginx-1.28.3.zip.asc"),
            keyring: PgpKeyring::embedded("nginx"),
        }),
    )
    .await
    .unwrap_err();
    assert_eq!(err.code(), "verification_failed");
}

#[tokio::test]
#[ignore = "downloads from nodejs.org"]
async fn nodejs_shasums_pgp_online() {
    let base = "https://nodejs.org/dist/v24.22.1";
    let dir = cache_dir().join("node-v24.22.1");
    std::fs::create_dir_all(&dir).unwrap();
    let mut paths = Vec::new();
    for name in ["SHASUMS256.txt", "SHASUMS256.txt.sig"] {
        let dest = dir.join(name);
        if !dest.is_file() {
            let harness = support::Harness::new(|c| {
                c.proxy = forge_provider::download::ProxySetting::System;
            });
            let mut events = harness.events();
            let job = harness
                .manager
                .download(forge_provider::download::DownloadRequest::new(
                    vec![format!("{base}/{name}").parse().unwrap()],
                    &dest,
                ))
                .await
                .unwrap();
            harness.wait_terminal(&mut events, job).await;
            assert_eq!(harness.jobs.get(job).unwrap().state, JobState::Done);
        }
        paths.push(dest);
    }
    let report = verify(
        &paths[0],
        Expect::unverified().signature(Signature::Pgp {
            sig_path: paths[1].clone(),
            keyring: PgpKeyring::embedded("nodejs"),
        }),
    )
    .await
    .unwrap();
    println!("{report:?}");
    match report.signature {
        Some(SignatureReport::Pgp { primary, .. }) => {
            let known = PgpKeyring::embedded("nodejs").fingerprints().unwrap();
            assert!(known.contains(&primary), "{primary}");
        }
        other => panic!("unexpected {other:?}"),
    }
    let text = std::fs::read_to_string(&paths[0]).unwrap();
    assert!(text.contains("node-v24.22.1-win-x64.zip"));
}
